/** The consent register — GET /api/v1/consents (who may call: holders of consent.view). */
export function listConsents(query?: { patient_id?: number | null; admission_id?: number | null; booking_id?: number | null; status?: "Draft" | "Given" | "Refused" | "Withdrawn" | "Cancelled" | null; category?: "General" | "Procedure" | "Anaesthesia" | "Transfusion" | "HighRiskTreatment" | "AgainstMedicalAdvice" | "Other" | null; date_from?: string | null; date_to?: string | null; unscanned?: boolean; limit?: number }): Promise<ConsentBriefOut[]> {
  return api<ConsentBriefOut[]>("GET", withQuery(`/consents`, query), undefined);
}

/** A consent — GET /api/v1/consents/{consent_id} (who may call: holders of consent.view). */
export function getConsent(consent_id: number): Promise<ConsentOut> {
  return api<ConsentOut>("GET", `/consents/${consent_id}`, undefined);
}

/** The consent form (A4) — GET /api/v1/consents/{consent_id}/print-payload (who may call: holders of consent.view). */
export function printConsent(consent_id: number): Promise<PrintOut_ConsentPrintFieldsOut_> {
  return api<PrintOut_ConsentPrintFieldsOut_>("GET", `/consents/${consent_id}/print-payload`, undefined);
}

/** The consent form as a PDF — GET /api/v1/consents/{consent_id}/pdf (who may call: holders of consent.view). */
export function consentPdf(consent_id: number): Promise<unknown> {
  return api<unknown>("GET", `/consents/${consent_id}/pdf`, undefined);
}

/** Consent statistics — GET /api/v1/consent-statistics (who may call: holders of consent.statistics.view). */
export function consentStatistics(query: { date_from: string; date_to: string }): Promise<ConsentStatisticsOut> {
  return api<ConsentStatisticsOut>("GET", withQuery(`/consent-statistics`, query), undefined);
}
